import pathlib,json,csv,hashlib,collections
R=pathlib.Path(__file__).resolve().parents[2]
O=R/'Components/phase1_closure';O.mkdir(exist_ok=True)
sources=json.loads((R/'SOURCES/components/closure_2026-09-15/manifest.json').read_text())
src={s['id']:s for s in sources}
rows=[]
for r in csv.DictReader((R/'Components/Proposed_Operating_Component_Set.csv').open(encoding='utf-8-sig')):
    custom=r['phase1_disposition'].startswith('CUSTOM')
    rows.append(dict(id=r['set_id'],segment=r['segment'],function=r['required_function'],quantity=r['quantity'],manufacturer=r['manufacturer'],part=r['exact_identifier_or_project_part'],description=r['proposed_component'],status='CUSTOM/TO BE VERIFIED' if custom else 'CANDIDATE / EVIDENCE INCOMPLETE',sources=r['source_ids'].split('; '),order_url=r['order_url'],dimensions_mass=r['known_size_and_mass'],power=r['known_power_or_generation'],interfaces=r['functional_basis'],uncertainty=r['evidence_or_design_gap'],blocked=r['blocked_release_or_analysis'],cost=r['cost_and_availability'],rationale=r['functional_basis'],verification='Not procurement released. See linked earlier property matrix and custom work packages.',included_in=None))
def get(i):return next(r for r in rows if r['id']==i)
def edit(i,**kw):get(i).update(kw)
def add(i,fn,part,details,interfaces,verify,sources=None,included=None,manufacturer='DEGENERATE-1',status='CUSTOM/TO BE VERIFIED',dm='Design not released; dimensions and mass unknown',power='To be established from connected loads',cost='Not quoted; no purchase made',url='Custom fabrication; no order release'):
    rows.append(dict(id=i,segment='Ground' if i.startswith(('GND','SUP')) else 'Flight',function=fn,quantity='1 assembly/set unless explicitly noted',manufacturer=manufacturer,part=part,description=details,status=status,sources=sources or [],order_url=url,dimensions_mass=dm,power=power,interfaces=interfaces,uncertainty=verify,blocked='Integrated build/operation release until the stated verification is complete',cost=cost,rationale='Necessary to implement the existing Earth-image mission or safely connect, assemble and operate its hardware',verification=verify,included_in=included))
