# Enrich every genuine custom part with a defined release path, without pretending detailed design exists.
specific={
'FLT-014':'Release schematic, regulator/protection IC BOM, layout and logic-level/backfeed analysis. Separate 5 V-derived regulated branches for OBC/radio and switched camera; prove voltage extrema below connected absolute maxima, current limit/retry behavior, thermal dissipation and single-fault containment with actual parts.',
'FLT-015':'Partition power, CAN/I2C/UART, switch/RBF and service harness branches; list every mating housing/contact/backshell and wire specification, gauge, length and termination. Require pin-to-pin drawing, continuity/insulation/voltage-drop tests, pull/strain-relief inspection and routing/bend/access review.',
'FLT-016':'AX100 MCX and proposed SAM-S MMCX endpoints are identified. Release exact 50-ohm cable, two connector part numbers and gender, length, bend/retention and workmanship; measure insertion/return loss at the authorized band against the existing <=1 dB assembly allocation.',
'FLT-017':'Design to piCAM/FM drawing and actual lens; release material/alloy/finish, M2.5 mating hardware, tolerances and baffle aperture. Verify retention, optical obstruction over field, fastener access, contamination and measured installed thermal path.',
'FLT-018':'Determine actual battery permitted temperature/charge conditions first. Release exact insulating/thermal material, thickness/area, compression/fasteners and surface preparation. Measure installed conductance and isolation across temperature; no generic conductance/density substituted.',
'FLT-019':'Create joint-by-joint fastener/standoff/washer/insert and bond-jumper schedule including manufacturer or drawing, alloy, length, thread engagement, locking method, torque and procurement quantity. Analyze joint loads and verify preload retention, bond continuity and access.',
'GND-006':'Separate static feedline, motion-rated flex loop, patch leads, adapters and weather seals. LMR-400 is only a static-run candidate; do not assume continuous-flex suitability. Freeze site lengths and endpoints, release exact cable/connector BOM, test installed loss/return loss, weather seals and full rotator travel.',
'GND-008':'Specify site, wind/ice/soil requirements, mast/foundation, nonconductive crossboom, anchors, bonds, entry surge protection and weather housing. Release drawings and exact hardware; independent structural/electrical review and installation inspection before use.'}
for r in rows:
 if r['id'] in specific:r['verification']=specific[r['id']]
 if r['status']=='CUSTOM/TO BE VERIFIED':
  r['design_state']='Requirements/work-package definition only; detailed design and constituent BOM not released'
  r['release_artifacts']=['Controlled drawing or schematic and interface pin map','Exact constituent BOM and material/process specifications','Analysis with source-backed properties and tolerances','Acceptance procedure with numerical criteria derived from connected equipment','As-built inspection and test record; independent review where required']
 else:r['design_state']='Manufacturer product proposal; not bought or tested'
 r['evidence_level']='DOCUMENTED' if r['status']=='SUPPORTED' else 'PROPOSED / DOCUMENTATION INCOMPLETE'
 r['mission_admitted']=False

counts=dict(collections.Counter(r['status'] for r in rows))
(O/'component_register.json').write_text(json.dumps(dict(document='D1-CMP-CLOSURE-001',date='2026-09-15',scope='Full proposed flight, ground and support set; unresolved exceptions retained honestly',gate='NOT CLOSED',counts=counts,items=rows),indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
out=['# Phase 1 consolidated proposed component register','', 'Revision A — 2026-09-15. **GATE NOT CLOSED. No complete spacecraft baseline is admitted.**','',f'{len(rows)} records: '+ '; '.join(f'{n} {k}' for k,n in counts.items())+'.','', '**SUPPORTED** means the specific component has adequate primary data for its stated bounded use; it does not establish the integrated installation, launch suitability or 12-month survival. **CUSTOM/TO BE VERIFIED** means a genuine custom work package, not fabricated design evidence. **CANDIDATE / EVIDENCE INCOMPLETE** is an explicit failed closure exception: the requested two-state end condition has not been reached. Removing this third state would conceal missing evidence.','', 'This register supersedes the 29-line operating proposal for the current review. It does not modify the controlled procurement BOM or authorize purchase. Alternative-only and included constituents are marked to avoid double counting. Unknown quantity, dimensions, mass, cost or current means unknown, never zero. No complete mass, power or cost total is defensible.','', 'Canonical data: `component_register.json`. Source IDs E01–E50 resolve in `source_index.md`; S identifiers resolve in `review/Source_Register.md` and `review/sources.json`. Archived manufacturer files stay local pending redistribution permission.','', '| ID | Function | Exact proposed part | State |','|---|---|---|---|']
for r in rows:out.append(f"| {r['id']} | {r['function']} | {r['part']} | {r['status']} |")
for r in rows:
 out+=['',f"## {r['id']} — {r['function']}",'']
 for key,label in [('status','State'),('manufacturer','Manufacturer/design authority'),('part','Part/configuration'),('quantity','Quantity'),('description','Description'),('included_in','Included/alternative relationship'),('dimensions_mass','Dimensions/mass'),('power','Power'),('interfaces','Interfaces'),('cost','Cost/availability'),('order_url','Order/reference route'),('rationale','Selection rationale'),('uncertainty','Remaining uncertainty'),('blocked','Blocked work'),('verification','Verification/release path'),('design_state','Design maturity')]:
  if r.get(key):out.append(f"- **{label}:** {r[key]}")
 out.append('- **Evidence:** '+', '.join(r['sources']))
 if 'release_artifacts'in r:out.append('- **Required release artifacts:** '+'; '.join(r['release_artifacts']))
(O/'component_register.md').write_text('\n'.join(out)+'\n',encoding='utf-8')
ix=['# Closure source index','', 'E identifiers are scoped to this closure review. Retrieval failures are preserved; a URL is not evidence of successful archival. Hashes identify the exact locally downloaded bytes, not independent validation of vendor claims. Document revisions should be checked in the linked document; do not infer a revision from the retrieval date.','', '| ID | Manufacturer document | Retrieval | SHA-256 |','|---|---|---|---|']
for s in sources:
 ix.append(f"| {s['id']} | [{s['title']}]({s['url']}) | {s['status']} ({s['retrieved_utc']}) | {s.get('sha256','NO ARCHIVED BYTES')} |")
 if s['status']=='RETRIEVED':
  (R/'SOURCES/components/closure_2026-09-15'/f"{s['id']}.url").write_text('[InternetShortcut]\nURL='+s['url']+'\n',encoding='utf-8')
ix+=['','Public web text was additionally reviewed for E03–E06, E24–E26 and current product pages E34–E41 where accessible; failed original downloads do not acquire hashes from that review. E16 is a Japanese manual and is not credited as a fully reviewed English command specification. E01/E02 current revisions were not obtained; older E24/E25 cannot silently stand in for them.','', 'The archive manifest retains retrieval time, exact URL, result, bytes and hash. No new authoritative qualification evidence was produced by this research.']
(O/'source_index.md').write_text('\n'.join(ix)+'\n',encoding='utf-8')
print(json.dumps(counts));print(len(rows))

